const cors = Cors({
  methods: ['GET', 'POST', 'OPTIONS'],
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',').map(o => o.trim()) : ['*'],
  credentials: true
});

function runMiddleware(req, res, fn) {
  return new Promise((resolve, reject) => {
    fn(req, res, (result) => {
      if (result instanceof Error) {
        return reject(result);
      }
      return resolve(result);
    });
  });
}

const redisConfig = {
  host: process.env.DRAGONFLY_URL || 'n5axicme3.dragonflydb.cloud',
  port: parseInt(process.env.DRAGONFLY_PORT || '6385'),
  password: process.env.DRAGONFLY_PASSWORD || '',
  tls: {},
  retryStrategy: (times) => Math.min(times * 50, 2000),
  maxRetriesPerRequest: 3
};

let redisClient = null;
let redisSessionClient = null;

function getRedisClient() {
  if (!redisClient && process.env.DRAGONFLY_PASSWORD) {
    redisClient = new Redis(redisConfig);
  }
  return redisClient;
}

function getSessionRedisClient() {
  if (!redisSessionClient && process.env.DRAGONFLY_PASSWORD) {
    redisSessionClient = new Redis({ ...redisConfig, db: 1 });
  }
  return redisSessionClient;
}

