const DEFAULT_HTTP_TIMEOUT = 30000;
const MAX_SSE_CLIENTS_PER_SESSION = 10;

const RESEARCH_SESSIONS = new Map();
const CONVERSATIONS = new Map();
const SSE_CLIENTS = new Map();

class DragonflyStorage {
  static CONV_PREFIX = "tiffytime:conv:";
  static RESEARCH_PREFIX = "tiffytime:research:";
  static USER_CONVS_PREFIX = "tiffytime:user_convs:";
  static USER_RESEARCH_PREFIX = "tiffytime:user_research:";
  static TTL_SECONDS = 365 * 24 * 60 * 60;

  static async saveConversation(convId, convData) {
    const client = getRedisClient();
    if (!client) return false;
    try {
      const key = `${this.CONV_PREFIX}${convId}`;
      await client.setex(key, this.TTL_SECONDS, JSON.stringify(convData));
      const userId = convData.user_id;
      if (userId) {
        const userKey = `${this.USER_CONVS_PREFIX}${userId}`;
        await client.sadd(userKey, convId);
        await client.expire(userKey, this.TTL_SECONDS);
      }
      return true;
    } catch (error) {
      console.error('Dragonfly save_conversation error:', error);
      return false;
    }
  }

  static async getConversation(convId) {
    const client = getRedisClient();
    if (!client) return null;
    try {
      const key = `${this.CONV_PREFIX}${convId}`;
      const data = await client.get(key);
      if (data) {
        return JSON.parse(data);
      }
      return null;
    } catch (error) {
      console.error('Dragonfly get_conversation error:', error);
      return null;
    }
  }

  static async deleteConversation(convId, userId) {
    const client = getRedisClient();
    if (!client) return false;
    try {
      const key = `${this.CONV_PREFIX}${convId}`;
      await client.del(key);
      const userKey = `${this.USER_CONVS_PREFIX}${userId}`;
      await client.srem(userKey, convId);
      return true;
    } catch (error) {
      console.error('Dragonfly delete_conversation error:', error);
      return false;
    }
  }

  static async getUserConversations(userId) {
    const client = getRedisClient();
    if (!client) return [];
    try {
      const userKey = `${this.USER_CONVS_PREFIX}${userId}`;
      const convIds = await client.smembers(userKey);
      const conversations = [];
      for (const convId of convIds) {
        const conv = await this.getConversation(convId);
        if (conv) conversations.push(conv);
      }
      return conversations;
    } catch (error) {
      console.error('Dragonfly get_user_conversations error:', error);
      return [];
    }
  }

  static async saveResearchSession(sessionId, sessionData) {
    const client = getRedisClient();
    if (!client) return false;
    try {
      const key = `${this.RESEARCH_PREFIX}${sessionId}`;
      await client.setex(key, this.TTL_SECONDS, JSON.stringify(sessionData));
      const userId = sessionData.user_id;
      if (userId) {
        const userKey = `${this.USER_RESEARCH_PREFIX}${userId}`;
        await client.sadd(userKey, sessionId);
        await client.expire(userKey, this.TTL_SECONDS);
      }
      return true;
    } catch (error) {
      console.error('Dragonfly save_research_session error:', error);
      return false;
    }
  }

  static async getResearchSession(sessionId) {
    const client = getRedisClient();
    if (!client) return null;
    try {
      const key = `${this.RESEARCH_PREFIX}${sessionId}`;
      const data = await client.get(key);
      if (data) {
        return JSON.parse(data);
      }
      return null;
    } catch (error) {
      console.error('Dragonfly get_research_session error:', error);
      return null;
    }
  }

  static async getUserResearchSessions(userId) {
    const client = getRedisClient();
    if (!client) return [];
    try {
      const userKey = `${this.USER_RESEARCH_PREFIX}${userId}`;
      const sessionIds = await client.smembers(userKey);
      const sessions = [];
      for (const sid of sessionIds) {
        const sess = await this.getResearchSession(sid);
        if (sess) sessions.push(sess);
      }
      return sessions;
    } catch (error) {
      console.error('Dragonfly get_user_research_sessions error:', error);
      return [];
    }
  }

  static async isConnected() {
    const client = getRedisClient();
    if (!client) return false;
    try {
      const result = await client.ping();
      return !!result;
    } catch {
      return false;
    }
  }
}

class ParallelClient {
  static MAX_RETRIES = 3;
  static POLL_INTERVAL = 30;
  static MAX_POLL_TIME = 3600;
  static BASE_URL = "";

  static _getHeaders() {
    if (!process.env.PARALLEL_API_KEY) return {};
    return {
      "x-api-key": process.env.PARALLEL_API_KEY,
      "Content-Type": "application/json"
    };
  }

  static isAvailable() {
    return !!process.env.PARALLEL_API_KEY;
  }

  static async _requestWithRetry(method, url, options = {}) {
    for (let attempt = 0; attempt < this.MAX_RETRIES; attempt++) {
      try {
        const response = await fetch(url, { method, ...options });
        if (response.status === 429 || response.status >= 500) {
          const waitTime = Math.pow(2, attempt) * 2000;
          console.warn(`Parallel API ${response.status}, retrying in ${waitTime}ms`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          continue;
        }
        return response;
      } catch (error) {
        console.error(`Parallel request error: ${error}`);
        if (attempt < this.MAX_RETRIES - 1) {
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 2000));
          continue;
        }
        return null;
      }
    }
    return null;
  }

  static async createDeepResearchTask(researchQuery, processor = "ultra", useTextMode = true) {
    if (!this.isAvailable()) {
      console.warn("Parallel API key not available");
      return null;
    }
    try {
      const payload = {
        input: researchQuery,
        processor: processor
      };
      if (useTextMode) {
        payload.task_spec = {
          output_schema: {
            type: "text",
            description: "Generate a comprehensive, analyst-grade research report with extensive inline citations. Conduct multi-step web exploration across all authoritative sources. Include detailed analysis, statistics, expert opinions, case studies, and future predictions. The report should be thorough and well-structured with clear sections."
          }
        };
      }
      const response = await this._requestWithRetry(
        'POST',
        `${this.BASE_URL}/tasks/runs`,
        {
          headers: this._getHeaders(),
          body: JSON.stringify(payload),
          timeout: DEFAULT_HTTP_TIMEOUT
        }
      );
      if (response && [200, 201, 202].includes(response.status)) {
        const result = await response.json();
        const runId = result.run_id;
        const status = result.status || 'unknown';
        console.info(`Parallel Deep Research task created: ${runId} (processor: ${processor}, status: ${status})`);
        return runId;
      } else if (response) {
        console.error(`Parallel task creation failed: ${response.status} - ${await response.text()}`);
      }
      return null;
    } catch (error) {
      console.error(`Parallel create task error: ${error}`);
      return null;
    }
  }

  static async getTaskStatus(runId) {
    if (!this.isAvailable()) return null;
    try {
      const response = await this._requestWithRetry(
        'GET',
        `${this.BASE_URL}/tasks/runs/${runId}`,
        {
          headers: this._getHeaders(),
          timeout: DEFAULT_HTTP_TIMEOUT
        }
      );
      if (response && response.status === 200) {
        return await response.json();
      }
      return null;
    } catch (error) {
      console.error(`Parallel get status error: ${error}`);
      return null;
    }
  }

  static async getTaskResult(runId) {
    if (!this.isAvailable()) return null;
    try {
      const response = await this._requestWithRetry(
        'GET',
        `${this.BASE_URL}/tasks/runs/${runId}/result`,
        {
          headers: this._getHeaders(),
          timeout: DEFAULT_HTTP_TIMEOUT
        }
      );
      if (response && response.status === 200) {
        return await response.json();
      }
      return null;
    } catch (error) {
      console.error(`Parallel get result error: ${error}`);
      return null;
    }
  }

  static async pollUntilComplete(runId, sessionId = null) {
    if (!this.isAvailable()) return null;
    const startTime = Date.now();
    let pollCount = 0;
    while ((Date.now() - startTime) < this.MAX_POLL_TIME * 1000) {
      pollCount++;
      const statusData = await this.getTaskStatus(runId);
      if (!statusData) {
        console.error(`Failed to get status for Parallel task ${runId}`);
        return null;
      }
      const status = statusData.status;
      console.info(`Parallel task ${runId} status: ${status} (poll #${pollCount})`);
      if (sessionId) {
        const elapsedMins = Math.floor((Date.now() - startTime) / 60000);
      }
      if (status === "completed") {
        const result = await this.getTaskResult(runId);
        if (result) {
          console.info(`Parallel Deep Research completed: ${runId}`);
          return result;
        }
        return null;
      } else if (status === "failed") {
        console.error(`Parallel task failed: ${runId}`);
        return null;
      }
      await new Promise(resolve => setTimeout(resolve, this.POLL_INTERVAL * 1000));
    }
    console.error(`Parallel task ${runId} timed out after ${this.MAX_POLL_TIME}s`);
    return null;
  }

  static async runDeepResearchSync(researchQuery, processor = "ultra", sessionId = null) {
    if (!this.isAvailable()) {
      console.warn("Parallel API not available - skipping");
      return null;
    }
    const runId = await this.createDeepResearchTask(researchQuery, processor, true);
    if (!runId) {
      console.error("Failed to create Parallel research task");
      return null;
    }
    const result = await this.pollUntilComplete(runId, sessionId);
    if (!result) {
      console.error(`Parallel research failed or timed out: ${runId}`);
      return null;
    }
    const output = result.output || {};
    if (typeof output === 'object' && output !== null) {
      const content = output.content || '';
      const basis = output.basis || [];
      if (typeof content === 'string' && content) {
        const citationsCount = Array.isArray(basis) ? basis.length : 0;
        console.info(`Parallel research completed: ${content.length} chars, ${citationsCount} citations`);
        return content;
      }
    }
    console.warning(`Parallel result format unexpected: ${typeof output}`);
    return output ? String(output) : null;
  }
}

class SuperMemoryClient {
  static MAX_RETRIES = 3;
  static BASE_URL = "";

  static _getHeaders() {
    if (!process.env.SUPERMEMORY_API_KEY) return {};
    return {
      Authorization: `Bearer ${process.env.SUPERMEMORY_API_KEY}`,
      "Content-Type": "application/json"
    };
  }

  static isAvailable() {
    return !!process.env.SUPERMEMORY_API_KEY;
  }

  static async _requestWithRetry(method, url, options = {}) {
    for (let attempt = 0; attempt < this.MAX_RETRIES; attempt++) {
      try {
        const response = await fetch(url, { method, ...options });
        if (response.status === 429 || response.status >= 500) {
          const waitTime = Math.pow(2, attempt) * 2000;
          console.warn(`SuperMemory API ${response.status}, retrying in ${waitTime}ms`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          continue;
        }
        return response;
      } catch (error) {
        console.error(`SuperMemory request error: ${error}`);
        if (attempt < this.MAX_RETRIES - 1) {
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 2000));
          continue;
        }
        return null;
      }
    }
    return null;
  }

  static async addMemory(content, metadata = null, containerTags = null, customId = null) {
    if (!this.isAvailable()) {
      console.debug("SuperMemory not available - API key missing");
      return null;
    }
    try {
      const payload = { content };
      if (metadata) payload.metadata = metadata;
      if (containerTags) payload.containerTags = containerTags;
      if (customId) payload.customId = customId;
      const response = await this._requestWithRetry(
        'POST',
        `${this.BASE_URL}/v3/documents`,
        {
          headers: this._getHeaders(),
          body: JSON.stringify(payload),
          timeout: DEFAULT_HTTP_TIMEOUT
        }
      );
      if (response && [200, 201].includes(response.status)) {
        const result = await response.json();
        console.info(`SuperMemory document added: ${result.id || 'unknown'}`);
        return result;
      } else if (response) {
        console.warning(`SuperMemory add failed: ${response.status} - ${await response.text()}`);
      }
      return null;
    } catch (error) {
      console.error(`SuperMemory add error: ${error}`);
      return null;
    }
  }

  static async searchMemories(query, limit = 10, containerTags = null, rerank = true) {
    if (!this.isAvailable()) return [];
    try {
      const payload = { q: query, limit: Math.min(limit, 50), rerank };
      if (containerTags) payload.containerTags = containerTags;
      const response = await this._requestWithRetry(
        'POST',
        `${this.BASE_URL}/v3/search`,
        {
          headers: this._getHeaders(),
          body: JSON.stringify(payload),
          timeout: DEFAULT_HTTP_TIMEOUT
        }
      );
      if (response && response.status === 200) {
        const result = await response.json();
        const memories = result.results || [];
        console.info(`SuperMemory search found ${memories.length} results for: ${query.substring(0, 50)}`);
        return memories;
      } else if (response) {
        console.warning(`SuperMemory search failed: ${response.status}`);
      }
      return [];
    } catch (error) {
      console.error(`SuperMemory search error: ${error}`);
      return [];
    }
  }

  static async searchMemoriesV4(query, limit = 10, userId = null, includeChunks = true) {
    if (!this.isAvailable()) return [];
    try {
      const payload = { q: query, limit: Math.min(limit, 50), includeChunks };
      if (userId) payload.filters = { "metadata.user_id": userId };
      const response = await this._requestWithRetry(
        'POST',
        `${this.BASE_URL}/v4/search`,
        {
          headers: this._getHeaders(),
          body: JSON.stringify(payload),
          timeout: DEFAULT_HTTP_TIMEOUT
        }
      );
      if (response && response.status === 200) {
        const result = await response.json();
        return result.results || [];
      } else if (response) {
        console.warning(`SuperMemory v4 search failed: ${response.status}`);
      }
      return [];
    } catch (error) {
      console.error(`SuperMemory v4 search error: ${error}`);
      return [];
    }
  }

  static async deleteMemory(documentId) {
    if (!this.isAvailable()) return false;
    try {
      const response = await this._requestWithRetry(
        'DELETE',
        `${this.BASE_URL}/v3/documents/${documentId}`,
        {
          headers: this._getHeaders(),
          timeout: DEFAULT_HTTP_TIMEOUT
        }
      );
      if (response && [200, 204].includes(response.status)) {
        console.info(`SuperMemory document deleted: ${documentId}`);
        return true;
      } else if (response) {
        console.warning(`SuperMemory delete failed: ${response.status}`);
      }
      return false;
    } catch (error) {
      console.error(`SuperMemory delete error: ${error}`);
      return false;
    }
  }

  static async addChatMemory(userId, conversationId, userMessage, assistantResponse) {
    const content = `Felhasználó kérdése: ${userMessage}

AI válasz: ${assistantResponse}`;
    const metadata = {
      type: "chat",
      user_id: userId,
      conversation_id: conversationId,
      timestamp: new Date().toISOString()
    };
    const result = await this.addMemory(
      content,
      metadata,
      ["chat", `user_${userId}`],
      `chat_${conversationId}_${uuidv4().substring(0, 8)}`
    );
    return result ? result.id : null;
  }

  static async addResearchMemory(userId, sessionId, goal, summary, sourcesCount) {
    const content = `Kutatási téma: ${goal}

Összefoglaló: ${summary}

Feldolgozott források száma: ${sourcesCount}`;
    const metadata = {
      type: "research",
      user_id: userId,
      session_id: sessionId,
      sources_count: sourcesCount,
      timestamp: new Date().toISOString()
    };
    const result = await this.addMemory(
      content,
      metadata,
      ["research", `user_${userId}`],
      `research_${sessionId}`
    );
    return result ? result.id : null;
  }

  static async getRelevantContext(userId, query, maxResults = 5) {
    const memories = await this.searchMemories(
      query,
      maxResults,
      [`user_${userId}`],
      true
    );
    if (!memories.length) return "";
    const contextParts = ["=== KORÁBBI RELEVÁNS INFORMÁCIÓK ==="];
    memories.slice(0, maxResults).forEach((mem, i) => {
      const chunks = mem.chunks || [];
      let relevantText = "";
      if (chunks.length) {
        relevantText = chunks[0].content ? chunks[0].content.substring(0, 500) : "";
      } else {
        relevantText = mem.content ? mem.content.substring(0, 500) : "";
      }
      if (relevantText) {
        contextParts.push(`\n[${i + 1}] ${relevantText}`);
      }
    });
    contextParts.push("\n=== KONTEXTUS VÉGE ===\n");
    return contextParts.join("\n");
  }
}

