function extractConfidenceFromResponse(response) {
  if (!response) return 0.75;
  const lines = response.trim().split('\n');
  for (let i = lines.length - 1; i >= Math.max(0, lines.length - 10); i--) {
    const lineLower = lines[i].toLowerCase();
    if (lineLower.includes('bizonyosság') || lineLower.includes('confidence') || lineLower.includes('%')) {
      const numbers = lines[i].match(/(\d+(?:\.\d+)?)/g);
      if (numbers) {
        try {
          let conf = parseFloat(numbers[numbers.length - 1]);
          if (conf > 1) conf = conf / 100.0;
          return Math.min(1.0, Math.max(0.0, conf));
        } catch (e) {
          continue;
        }
      }
    }
  }
  return 0.75;
}

function generateSimpleEmbedding(text) {
  if (!text || typeof text !== 'string') return new Array(256).fill(0.0);
  const normalizedText = text.toLowerCase().substring(0, 10000);
  const embedding = [];
  for (let i = 0; i < 256; i++) {
    const hash = crypto.createHash('md5').update(`${normalizedText}_${i}`).digest('hex');
    embedding.push(parseInt(hash.substring(0, 8), 16) / Math.pow(16, 8));
  }
  const norm = Math.sqrt(embedding.reduce((sum, val) => sum + val * val, 0));
  if (norm > 0) {
    return embedding.map(x => x / norm);
  }
  return embedding;
}

async function runSingleExpertAgent(agentId, perspective, goal, context = "", webResults = null, sessionId = null) {
  const systemPrompt = PERSPECTIVE_SYSTEM_PROMPTS[perspective] || "";
  let userMessage = `Kutatási feladat: ${goal}\n\n`;
  if (context) {
    userMessage += `Kontextus:\n${truncateText(context, 3000)}\n\n`;
  }
  if (webResults) {
    userMessage += "Webes források:\n";
    webResults.slice(0, 100).forEach((result, i) => {
      const title = (result.title || 'N/A').substring(0, 100);
      const url = (result.url || '').substring(0, 200);
      const text = (result.text || '').substring(0, 300);
      userMessage += `${i + 1}. ${title}\n   URL: ${url}\n   Kivonat: ${text}\n`;
    });
  }
  userMessage += "\nKérlek végezz alapos kutatást. Strukturáld: 1. Fő megállapítások 2. Részletes elemzés 3. Bizonyossági szint (0-100%)";
  try {
    const result = await callTiffyApi(systemPrompt, userMessage, {
      maxTokens: 250000,
      temperature: 0.7,
      includeReasoning: true,
      sessionId
    });
    const confidence = extractConfidenceFromResponse(result.content);
    const embedding = generateSimpleEmbedding(result.content);
    const sources = webResults ? webResults.slice(0, 5).map(r => ({ url: r.url || '', title: r.title || '' })) : [];
    return {
      agent_id: agentId,
      perspective,
      response: result.content,
      confidence,
      sources,
      processing_time: result.processing_time,
      tokens_used: result.tokens_used,
      embedding,
      tool_calls: result.tool_calls || [],
      citations: result.citations || [],
      error: null
    };
  } catch (error) {
    console.error(`Agent ${agentId} failed: ${error}`);
    return {
      agent_id: agentId,
      perspective,
      response: "",
      error: String(error),
      confidence: 0.0,
      sources: [],
      processing_time: 0,
      tokens_used: 0,
      embedding: null,
      tool_calls: [],
      citations: []
    };
  }
}

