function secureFilename(filename) {
  let safeName = path.basename(filename);
  safeName = safeName.replace(/[^a-zA-Z0-9-_.]/g, '');
  if (!safeName || safeName.startsWith('.')) {
    safeName = 'file_' + safeName.replace(/^\.+/, '');
  }
  return safeName.substring(0, 255);
}

function truncateText(text, maxLength = 500) {
  return text && text.length > maxLength ? text.substring(0, maxLength) : (text || "");
}

function escapeHtml(text) {
  if (typeof text !== 'string') return text;
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function validateUrl(url) {
  if (typeof url !== 'string') return '';
  url = url.trim();
  if (!url.startsWith('http://') && !url.startsWith('https://')) return '';
  return escapeHtml(url);
}

function validateFileSize(size, maxSize = 100 * 1024 * 1024) {
  return size > 0 && size <= maxSize;
}

function sanitizeFilename(filename) {
  return filename.replace(/\.\./g, '').replace(/\//g, '').replace(/\\/g, '').substring(0, 255);
}

function validateGoal(goal) {
  if (!goal || typeof goal !== 'string') throw new Error("Kutatási cél szükséges");
  goal = goal.trim();
  if (goal.length < 5) throw new Error("Kutatási cél túl rövid (min 5 karakter)");
  if (goal.length > 5000) throw new Error("Kutatási cél túl hosszú (max 5000 karakter)");
  return goal;
}

function validateMessage(message) {
  if (!message || typeof message !== 'string') throw new Error("Üzenet szükséges");
  message = message.trim();
  if (message.length < 1) throw new Error("Üzenet nem lehet üres");
  if (message.length > 10000) throw new Error("Üzenet túl hosszú");
  return message;
}

async function processUploadedFile(file) {
  if (!file || !file.originalFilename) throw new Error("Nincs fájl kiválasztva");
  const filename = sanitizeFilename(file.originalFilename);
  const fileSize = file.size;
  if (!validateFileSize(fileSize)) throw new Error("Fájl túl nagy (max 100MB)");
  const storedFilename = `${uuidv4()}_${filename}`;
  const filepath = path.join(UPLOAD_FOLDER, storedFilename);
  const content = "";
  return {
    filename: file.originalFilename,
    stored_filename: storedFilename,
    filepath,
    content,
    size: fileSize
  };
}

async function callTiffyApi(systemPrompt, userMessage, options = {}) {
  const {
    maxTokens = 2000000,
    temperature = 0.7,
    includeReasoning = false,
    sessionId = null,
    maxRetries = 3,
    enableTools = false,
    attachedImages = null
  } = options;

  const apiKey = process.env.XAI_API_KEY;
  if (!apiKey) throw new Error("XAI_API_KEY not set");

  const headers = {
    Authorization: `Bearer ${apiKey}`,
    "Content-Type": "application/json"
  };

  const payload = {
    model: "grok-4-1-fast",
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userMessage }
    ],
    max_tokens: maxTokens,
    temperature: Math.max(0.0, Math.min(2.0, temperature)),
    stream: includeReasoning
  };

  if (includeReasoning) {
    payload.reasoning = { effort: "high" };
  }

  if (enableTools) {
    payload.tools = [
      {
        type: "function",
        function: {
          name: "web_search",
          description: "Search the web for information",
          parameters: { query: { type: "string" } }
        }
      },
      {
        type: "function",
        function: {
          name: "twitter_search",
          description: "Search X (Twitter) for real-time information",
          parameters: { query: { type: "string" } }
        }
      },
      {
        type: "function",
        function: {
          name: "execute_python_code",
          description: "Execute Python code for calculations or data manipulation",
          parameters: { code: { type: "string" } }
        }
      },
      {
        type: "function",
        function: {
          name: "analyze_data",
          description: "Perform data analysis and generate visualizations",
          parameters: { data: { type: "string" }, analysis_type: { type: "string" } }
        }
      },
      {
        type: "function",
        function: {
          name: "understand_image",
          description: "Analyze and understand image content",
          parameters: { image_url: { type: "string" } }
        }
      }
    ];
    payload.tool_choice = "auto";
  }

  if (attachedImages) {
    payload.images = attachedImages;
  }

  let lastError = null;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    const startTime = Date.now();
    try {
      if (includeReasoning && sessionId) {
        const response = await fetch("", {
          method: 'POST',
          headers,
          body: JSON.stringify(payload),
          timeout: 180000
        });

        if (response.status === 429) {
          const waitTime = Math.pow(2, attempt) * 2000;
          console.warn(`Tiffy API rate limited (429), retrying in ${waitTime}ms`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          continue;
        }

        if (response.status !== 200) {
          throw new Error(`Tiffy API returned ${response.status}`);
        }

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let content = "";
        let reasoningContent = "";
        let toolCalls = [];
        let citations = [];
        let tokensUsed = 0;

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          const chunk = decoder.decode(value);
          const lines = chunk.split('\n');
          for (const line of lines) {
            if (line.startsWith('data: ')) {
              const jsonStr = line.substring(6);
              if (jsonStr.trim() === '[DONE]') break;
              try {
                const data = JSON.parse(jsonStr);
                const delta = data.choices[0]?.delta || {};
                if (delta.reasoning_content) {
                  reasoningContent += delta.reasoning_content;
                }
                if (delta.tool_calls) {
                  toolCalls.push(...delta.tool_calls);
                }
                if (delta.citations) {
                  citations.push(...delta.citations);
                }
                if (delta.content) {
                  content += delta.content;
                }
                if (data.usage) {
                  tokensUsed = data.usage.total_tokens || 0;
                }
              } catch (e) {
                continue;
              }
            }
          }
        }

        const processingTime = (Date.now() - startTime) / 1000;
        return {
          content,
          reasoning: reasoningContent,
          tool_calls: toolCalls,
          citations,
          tokens_used: tokensUsed,
          processing_time: processingTime
        };
      } else {
        const nonStreamPayload = { ...payload };
        nonStreamPayload.stream = false;
        delete nonStreamPayload.reasoning;

        const response = await fetch("", {
          method: 'POST',
          headers,
          body: JSON.stringify(nonStreamPayload),
          timeout: 180000
        });

        if (response.status === 429) {
          const waitTime = Math.pow(2, attempt) * 2000;
          console.warn(`Tiffy API rate limited (429), retrying in ${waitTime}ms`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          continue;
        }

        if (response.status !== 200) {
          throw new Error(`Tiffy API returned ${response.status}`);
        }

        const result = await response.json();
        const content = result.choices[0].message.content;
        const tokensUsed = result.usage?.total_tokens || 0;
        const toolCalls = result.choices[0]?.message?.tool_calls || [];
        const citations = result.choices[0]?.message?.citations || [];
        const processingTime = (Date.now() - startTime) / 1000;

        return {
          content,
          tokens_used: tokensUsed,
          processing_time: processingTime,
          tool_calls: toolCalls,
          citations
        };
      }
    } catch (error) {
      lastError = error;
      console.error(`Tiffy API error: ${error}`);
      if (error.message.includes('429') && attempt < maxRetries - 1) {
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 2000));
        continue;
      }
      throw error;
    }
  }
  throw lastError || new Error("Max retries exceeded");
}

async function callExaSearch(query, numResults = 100, searchType = "auto", useDeep = false) {
  const apiKey = process.env.EXA_API_KEY;
  if (!apiKey) return [];
  const headers = { "x-api-key": apiKey, "Content-Type": "application/json" };
  const actualType = useDeep ? "deep" : searchType;
  const payload = {
    query,
    numResults,
    type: actualType,
    text: true,
    livecrawl: "always",
    highlights: { numSentences: 10, highlightsPerUrl: 5 }
  };
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const response = await fetch("", {
        method: 'POST',
        headers,
        body: JSON.stringify(payload),
        timeout: 60000
      });
      if (response.status === 429 || response.status >= 500) {
        const waitTime = Math.pow(2, attempt) * 2000;
        console.warn(`Exa search rate limited, retrying in ${waitTime}ms`);
        await new Promise(resolve => setTimeout(resolve, waitTime));
        continue;
      }
      if (response.status !== 200) {
        console.warning(`Exa search failed: ${response.status}`);
        return [];
      }
      const result = await response.json();
      return result.results || [];
    } catch (error) {
      console.error(`Exa search error: ${error}`);
      if (attempt < 2) {
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 2000));
        continue;
      }
      return [];
    }
  }
  return [];
}

function extractConfidenceFromResponse(response) {
  if (!response) return 0.75;
  const lines = response.trim().split('\n');
  for (let i = lines.length - 1; i >= Math.max(0, lines.length - 10); i--) {
    const lineLower = lines[i].toLowerCase();
    if (lineLower.includes('bizonyosság') || lineLower.includes('confidence') || lineLower.includes('%')) {
      const numbers = lines[i].match(/(\d+(?:\.\d+)?)/g);
      if (numbers) {
        try {
          let conf = parseFloat(numbers[numbers.length - 1]);
          if (conf > 1) conf = conf / 100.0;
          return Math.min(1.0, Math.max(0.0, conf));
        } catch (e) {
          continue;
        }
      }
    }
  }
  return 0.75;
}

function generateSimpleEmbedding(text) {
  if (!text || typeof text !== 'string') return new Array(256).fill(0.0);
  const normalizedText = text.toLowerCase().substring(0, 10000);
  const embedding = [];
  for (let i = 0; i < 256; i++) {
    const hash = crypto.createHash('md5').update(`${normalizedText}_${i}`).digest('hex');
    embedding.push(parseInt(hash.substring(0, 8), 16) / Math.pow(16, 8));
  }
  const norm = Math.sqrt(embedding.reduce((sum, val) => sum + val * val, 0));
  if (norm > 0) {
    return embedding.map(x => x / norm);
  }
  return embedding;
}

