      includeReasoning: true,
      sessionId
    });
    const confidence = extractConfidenceFromResponse(result.content);
    const embedding = generateSimpleEmbedding(result.content);
    const sources = webResults ? webResults.slice(0, 5).map(r => ({ url: r.url || '', title: r.title || '' })) : [];
    return {
      agent_id: agentId,
      perspective,
      response: result.content,
      confidence,
      sources,
      processing_time: result.processing_time,
      tokens_used: result.tokens_used,
      embedding,
      tool_calls: result.tool_calls || [],
      citations: result.citations || [],
      error: null
    };
  } catch (error) {
    console.error(`Agent ${agentId} failed: ${error}`);
    return {
      agent_id: agentId,
      perspective,
      response: "",
      error: String(error),
      confidence: 0.0,
      sources: [],
      processing_time: 0,
      tokens_used: 0,
      embedding: null,
      tool_calls: [],
      citations: []
    };
  }
}

async function callCerebrasChat(messages, maxTokens = 65000, temperature = 1.0, topP = 0.95, maxRetries = 3) {
  const apiKey = process.env.CEREBRAS_API_KEY;
  if (!apiKey) throw new Error("CEREBRAS_API_KEY not set");
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const response = await fetch("", {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          model: "gpt-oss-120b",
          max_tokens: maxTokens,
          messages,
          temperature: Math.max(0.0, Math.min(2.0, temperature)),
          top_p: Math.max(0.0, Math.min(1.0, topP))
        }),
        timeout: 60000
      });
      if (!response.ok) {
        const errorText = await response.text();
        const isRetryable = /429|rate limit|timeout|500|502|503|504/i.test(errorText);
        if (isRetryable && attempt < maxRetries - 1) {
          const waitTime = Math.pow(2, attempt) * 2000;
          console.warn(`Cerebras chat error, retrying in ${waitTime}ms`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          continue;
        }
        throw new Error(`Cerebras API error: ${response.status} - ${errorText}`);
      }
      const result = await response.json();
      return result.choices[0]?.message?.content || "";
    } catch (error) {
      const errorStr = String(error).toLowerCase();
      const isRetryable = /429|rate limit|timeout|500|502|503|504/.test(errorStr);
      if (isRetryable && attempt < maxRetries - 1) {
        const waitTime = Math.pow(2, attempt) * 2000;
        console.warn(`Cerebras chat error, retrying in ${waitTime}ms`);
        await new Promise(resolve => setTimeout(resolve, waitTime));
        continue;
      }
      throw error;
    }
  }
  return "";
}

async function broadcastSseEvent(sessionId, data) {
  const eventData = { ...data, timestamp: new Date().toISOString() };
  const clients = SSE_CLIENTS.get(sessionId) || [];
  clients.forEach(queueObj => {
    try {
      if (!queueObj.full) {
        queueObj.push(eventData);
      }
    } catch (error) {
      console.warning(`SSE queue error for session ${sessionId}: ${error}`);
    }
  });
}

